const paths={bag:'M6 7h12l2 14H4L6 7Zm3 0V5a3 3 0 0 1 6 0v2',food:'M4 3v7a2 2 0 0 0 4 0V3M6 3v18M16 3c-3 4-3 9 0 9h3M19 3v18',box:'m3 7 9-5 9 5v10l-9 5-9-5V7Zm0 0 9 5 9-5M12 12v10M8 4l9 5',bolt:'m13 2-9 12h7l-1 8L21 9h-8l1-7',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0ZM15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',shield:'m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6l9-4Zm-4 10 3 3 5-6',clock:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0ZM12 6v6l4 2',heart:'M20 4c-3-3-7-1-8 2-1-3-5-5-8-2-5 5 2 11 8 16 6-5 13-11 8-16',bike:'M8 17a4 4 0 1 1-8 0 4 4 0 0 1 8 0ZM24 17a4 4 0 1 1-8 0 4 4 0 0 1 8 0ZM4 17l5-9 5 9H4M9 8h7l4 9M7 5h4M15 4h3l2 4',shop:'M3 10v11h18V10M2 3h20l-2 7H4L2 3ZM9 21v-7h6v7',check:'m5 12 4 4L19 6',arrow:'M4 12h16m-6-6 6 6-6 6',user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0ZM4 22v-3a8 8 0 0 1 16 0v3'};
const icon=(name,cls='')=>`<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.bag}"/></svg>`;
const mark=`<svg viewBox="0 0 42 42" fill="none" aria-hidden="true"><rect width="42" height="42" rx="12" fill="#08794b"/><path d="M29 12H19a9 9 0 1 0 0 18h9l3-6H19a3 3 0 0 1 0-6h8z" fill="#d6f281"/><path d="M4 17h6M2 23h7" stroke="#d6f281" stroke-width="2.3" stroke-linecap="round"/></svg>`;
const brand=(original=false)=>original?`<a href="#/" class="original-brand" aria-label="Cartman PH home"><img src="assets/cartman-logo.png" alt="Cartman PH — Everything. Delivered."></a>`:`<a href="#/" class="brand" aria-label="Cartman PH home">${mark}<span>CARTMAN<em>PH</em></span></a>`;
const services=[{name:'Food delivery',key:'food',copy:'Your cravings, taken care of. Good food from your neighborhood favorites.',label:'Find your next bite',color:'food'},{name:'Groceries',key:'bag',copy:'Fresh picks and pantry essentials. More time for what matters.',label:'Fill your basket',color:'grocery'},{name:'Send a parcel',key:'box',copy:'From a little surprise to an important package. Send it with care.',label:'Make a delivery',color:'parcel'},{name:'Pabili & errands',key:'bolt',copy:'A few things on your list? Let us take the extra trip for you.',label:'Get a helping hand',color:'errands'}];
const $=s=>document.querySelector(s);let slide=0,slideTimer,role='customer';
const safe=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const read=(key,fallback=null)=>{try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}};
const save=(key,value)=>{try{localStorage.setItem(key,JSON.stringify(value))}catch{toast('Browser storage is unavailable. This session may not be saved.')}};
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');setTimeout(()=>$('#toast').classList.remove('visible'),4000)}
function header(){const user=read('cartman-session');$('#header').innerHTML=`<div class="announcement">A little less to do. <span>A little more life to live.</span> &nbsp; Meet Cartman PH ↗</div><div class="wrap nav">${brand(true)}<nav class="navlinks" aria-label="Main navigation"><a href="#/services">Our services</a><a href="#/how-it-works">How it works</a><a href="#/partners">Become a partner</a><a href="#/help">Help center</a></nav><div class="nav-actions"><a class="textlink" href="#/${user?'account':'login'}">${user?'My account':'Log in'}</a><a class="btn" href="#/book">Book a delivery <span>↗</span></a><button class="menu-toggle" aria-label="Open navigation" aria-expanded="false">☰</button></div></div>`;$('.menu-toggle').onclick=e=>{const open=$('.navlinks').classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',open)}}
function footer(){$('#footer').innerHTML=`<div class="footer"><div class="wrap"><div class="footer-grid"><div>${brand()}<p>For the everyday. For the unexpected.<br>Everything, delivered.</p></div><div><h4>Explore Cartman</h4><div class="footer-links"><a href="#/services">Our services</a><a href="#/how-it-works">How it works</a><a href="#/track">Track a delivery</a></div></div><div><h4>Grow with us</h4><div class="footer-links"><a href="#/partners?type=rider">Become a rider</a><a href="#/partners?type=merchant">Partner your business</a><a href="#/about">Our story</a></div></div><div><h4>We're here for you</h4><div class="footer-links"><a href="#/help">Help center</a><a href="#/help?contact=1">Contact us</a><a href="#/login">Your account</a></div></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} Cartman PH. Everything. Delivered.</span><span><a href="#/privacy">Privacy policy</a> &nbsp; · &nbsp; <a href="#/terms">Terms of service</a></span><span>Made for everyday Filipino life. ↗</span></div></div></div>`}
const serviceCards=()=>`<div class="service-grid">${services.map(s=>`<a class="service-card" href="#/book?service=${s.color}"><div class="service-icon">${icon(s.key)}</div><h3>${s.name}</h3><p>${s.copy}</p><span class="textlink">${s.label} <span>↗</span></span></a>`).join('')}</div>`;
const steps=()=>`<div class="steps"><div><div class="step-num">01 <span>CHOOSE</span></div><h3>A little help starts here.</h3><p>Pick what you need, from a favorite meal to an everyday errand.</p></div><div><div class="step-num">02 <span>BOOK</span></div><h3>Your details. Your schedule.</h3><p>Add your locations and delivery notes, then review your estimate.</p></div><div><div class="step-num">03 <span>RELAX</span></div><h3>Get back to your day.</h3><p>Follow your delivery's journey. We'll take care of the little trip.</p></div></div>`;
const faq=()=>`<div class="faq"><h2>A few things you<br>might be wondering.</h2>${[['What can I book with Cartman?','Explore food delivery, groceries, parcels, and pabili errands in this MVP. These are demonstration journeys; live service availability will be confirmed before launch.'],['Where is Cartman available?','This preview illustrates a Philippines delivery experience. Launch locations and actual coverage have not yet been announced.'],['How much does a delivery cost?','The booking tool shows an illustrative estimate based on service and distance. All amounts are demo prices, not live quotes.'],['Can I track my delivery?','Yes. Create a demo booking and open its tracking page, or try reference CM-DEMO. No actual rider is dispatched in this preview.']].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div>`;
function home(){return `<section class="hero"><div class="wrap"><div class="hero-grid"><div class="hero-copy"><div class="eyebrow">Life moves. We deliver.</div><h1>Your day.<br>Your way.<br><span>Delivered.</span></h1><p>Good food. Fresh essentials. Little errands.<br>Whatever your day needs, let Cartman bring it to you.</p><div class="hero-ctas"><a class="btn" href="#/book">What do you need? <span class="arrow">↗</span></a><a class="textlink" href="#/how-it-works">How it works <span>↗</span></a></div><div class="hero-note"><span class="miniicon">✓</span> A little help. A whole lot of possibilities.</div></div><div class="hero-media" aria-roledescription="carousel" aria-label="Cartman campaign"><img id="hero-image" src="assets/hero-delivery.webp" alt="A Filipino courier delivers fresh groceries to a smiling customer"><div class="media-shade"></div><div class="floating-tag"><span class="tag-icon">✓</span><div><strong>Good things are on the way.</strong><small>A little doorstep happiness.</small></div></div><div class="campaign-label" id="campaign-label">More moments.<br>Fewer errands.</div><div class="delivery-tag"><strong>Made for your everyday.</strong>From our neighborhood to yours.</div><div class="hero-controls"><div class="dots">${[0,1,2].map(i=>`<button class="${i===0?'active':''}" data-slide="${i}" aria-label="Show campaign ${i+1}" aria-pressed="${i===0}"></button>`).join('')}</div><div class="slide-buttons"><button id="pause-slide" aria-label="Pause slideshow">Ⅱ</button><button data-direction="-1" aria-label="Previous slide">←</button><button data-direction="1" aria-label="Next slide">→</button></div></div></div></div><div class="service-strip">${[['pin','Your neighborhood, connected','Everyday needs, closer to you'],['shield','Care in every delivery','From pickup to your doorstep'],['clock','More time for you','Leave the little trips to us'],['heart','People at the heart','Built around your everyday']].map(([i,t,d])=>`<div class="strip-item">${icon(i)}<div><strong>${t}</strong><span>${d}</span></div></div>`).join('')}</div></div></section><section class="section"><div class="wrap"><div class="section-head"><div class="section-title"><div class="eyebrow">One Cartman. So many possibilities.</div><h2>Whatever's on your list.</h2></div><p>Big cravings, small errands, and everything in between. We've got a way to help.</p></div>${serviceCards()}</div></section><section class="section steps-section"><div class="wrap"><div class="section-head"><div><div class="eyebrow">Simple from the start</div><h2>Less to do. More you.</h2></div><a class="textlink" href="#/book">Let's get started ↗</a></div>${steps()}</div></section><section class="section"><div class="wrap"><div class="app-section"><div><div class="eyebrow">Your everyday, in your pocket</div><h2>Big help.<br>One little app.</h2><p>Your meals, essentials, and deliveries. A simpler way to get through your everyday is on its way.</p><a class="btn light" href="#/waitlist">Be first to know <span>↗</span></a><p style="font-size:10px;margin:15px 0 0">The Cartman app is coming. Join the launch interest list.</p></div><div class="phone-scene"><div class="orbit"></div><div class="orbit two"></div><div class="phone">${brand()}<small>Your day looks good.</small><h3>What do you<br>need today?</h3><div class="phone-grid">${services.map(s=>`<div class="phone-tile">${icon(s.key)}${s.name}</div>`).join('')}</div><div class="phone-status">A little doorstep happiness. ↗<br><strong>Everything. Delivered.</strong></div></div><div class="float-pill">✓ &nbsp; More time for what you love.</div></div></div></div></section><section class="section" style="padding-top:10px"><div class="wrap"><div class="section-head"><div><div class="eyebrow">Go further, together</div><h2>There's a place for you here.</h2></div><p>People with places to go. Businesses with room to grow. Let's make things happen.</p></div><div class="partners"><article class="partner-card">${icon('bike')}<h3>Your next chapter.<br>On two wheels.</h3><p>Turn your drive into opportunity. Discover what it means to ride with Cartman.</p><a class="textlink" href="#/partners?type=rider">Become a rider <span>↗</span></a></article><article class="partner-card">${icon('shop')}<h3>Local favorites.<br>New possibilities.</h3><p>Bring your business to more doorsteps. Let's help your neighborhood discover you.</p><a class="textlink" href="#/partners?type=merchant">Partner with us <span>↗</span></a></article></div></div></section><section class="section"><div class="wrap">${faq()}</div></section>`}
function intro(eye,title,copy){return `<div class="page-intro"><div class="eyebrow">${eye}</div><h1>${title}</h1>${copy?`<p>${copy}</p>`:''}</div>`}
function field(label,name,type='text',placeholder='',required=true){return `<label class="field">${label}<input type="${type}" name="${name}" placeholder="${placeholder}" ${required?'required':''} ${type==='password'?'minlength="8" autocomplete="new-password"':''} ${type==='email'?'autocomplete="email"':''}></label>`}
function auth(signup=false){return intro('Your everyday starts here',signup?'Make room for more.':'Good to have you back.',signup?'Create your Cartman account and make the little trips a little easier.':'Your next delivery is just a few details away.')+`<div class="form-shell"><div class="form-content"><div class="notice">Interactive UI preview. Use sample details only. No real authentication is connected, and passwords are never stored.</div><div class="tabs" role="group" aria-label="Account type">${['customer','rider','merchant'].map(r=>`<button type="button" data-role="${r}" class="${role===r?'active':''}">${r[0].toUpperCase()+r.slice(1)}</button>`).join('')}</div><form id="auth-form">${signup?field('Full name','name','text','Juan Dela Cruz'):''}${field('Email address','email','email','you@example.com')}${field('Password','password','password','At least 8 characters')}${signup?'<label class="check"><input type="checkbox" required><span>I agree to the <a href="#/terms">demo terms</a> and <a href="#/privacy">privacy notice</a>.</span></label>':'<div style="text-align:right;margin:-5px 0 20px"><a class="textlink" href="#/forgot-password">Forgot password?</a></div>'}<button class="btn full">${signup?'Create demo account':'Log in to demo'} <span>↗</span></button><p class="form-foot">${signup?'Already have an account? <a href="#/login">Log in</a>':'New around here? <a href="#/signup">Create an account</a>'}</p></form></div><aside class="form-side"><div class="service-icon">${icon('heart')}</div><h3>A little help.<br>A better everyday.</h3><p>Meals worth sharing. Errands made easier. More time for the people who matter.</p><img src="assets/cartman-logo.png" alt="Cartman PH: Everything. Delivered." style="width:100%;mix-blend-mode:multiply;margin-top:25px"></aside></div>`}
function book(params){const selected=params.get('service')||'parcel';return intro('One less thing on your list','Let’s get it delivered.','A few details, and you’re one step closer to getting on with your day.')+`<div class="form-shell"><div class="form-content"><a class="back-link" href="#/services">← All services</a><h2>Your delivery details</h2><div class="notice">Demo booking only. Estimates are illustrative; no payment is collected and no rider is dispatched.</div><form id="booking-form"><label class="field">What do you need?<select name="service" id="service-select">${services.map(s=>`<option value="${s.color}" ${s.color===selected?'selected':''}>${s.name}</option>`).join('')}</select></label>${field('Pickup address','pickup','text','Street, barangay, city')}${field('Drop-off address','dropoff','text','Building, street, barangay, city')}<div class="field-row">${field('Recipient name','recipient','text','Juan Dela Cruz')}${field('Recipient mobile','phone','tel','09XX XXX XXXX')}</div><div class="field-row"><label class="field">Estimated distance<select name="distance" id="distance"><option value="3">Up to 3 km</option><option value="5">3–5 km</option><option value="10">5–10 km</option><option value="15">10–15 km</option></select></label><label class="field">When?<select name="schedule"><option>As soon as possible</option><option>Today, 2–4 PM (demo)</option><option>Tomorrow, 9–11 AM (demo)</option></select></label></div><label class="field">Delivery notes (optional)<textarea name="notes" placeholder="Items, landmarks, or anything we should know"></textarea></label><button class="btn full">Review delivery <span>↗</span></button></form></div><aside class="form-side"><div class="service-icon">${icon('box')}</div><h3>Good things.<br>On their way.</h3><p>Review your details before confirming. Your delivery stays in this browser for the demo.</p><div class="estimate"><small>Illustrative delivery estimate</small><strong id="estimate">₱79</strong><small>Delivery only. Item purchases not included.<br>Final live rates are not yet available.</small></div></aside></div>`}
let pendingBooking=null;
function estimate(){const base={food:49,grocery:69,parcel:49,errands:89};return base[$('#service-select').value]+Number($('#distance').value)*10}
function review(){if(!pendingBooking){location.hash='/book';return ''}const b=pendingBooking;return intro('Just one more look','Everything look right?','Review your demo delivery before you confirm.')+`<div class="status-card"><div class="notice">This is a simulated booking. No real delivery or payment will take place.</div><h3>${safe(services.find(s=>s.color===b.service)?.name)}</h3><p><strong>Pickup</strong><br>${safe(b.pickup)}</p><p><strong>Drop-off</strong><br>${safe(b.dropoff)}</p><p><strong>Recipient</strong><br>${safe(b.recipient)} · ${safe(b.phone)}</p><p><strong>Schedule</strong><br>${safe(b.schedule)}</p>${b.notes?`<p><strong>Notes</strong><br>${safe(b.notes)}</p>`:''}<div class="estimate"><small>Illustrative total</small><strong>₱${b.total}</strong></div><div style="display:flex;gap:15px;margin-top:25px"><button id="confirm-booking" class="btn">Confirm demo booking ↗</button><a href="#/book" class="btn outline">Edit details</a></div></div>`}
function track(params){const id=params.get('id');const bookings=read('cartman-bookings',[]);const b=bookings.find(x=>x.id.toLowerCase()===id?.toLowerCase());const isDemo=id?.toUpperCase()==='CM-DEMO';return intro('A little peace of mind','Follow the little journey.','Enter your demo booking reference to see where things stand.')+`<div class="status-card"><form id="track-form"><label class="field">Booking reference<input name="reference" required placeholder="e.g. CM-DEMO" value="${safe(id||'')}"></label><button class="btn full">Track delivery ↗</button></form>${id?(b||isDemo?`<div class="result"><div class="status-title"><div><small>DEMO DELIVERY</small><h3 style="margin:6px 0">${safe(id.toUpperCase())}</h3></div><span class="badge">Booking confirmed</span></div><p>${b?`${safe(b.pickup)} → ${safe(b.dropoff)}`:'Illustrative pickup → Your doorstep'}</p></div><div class="timeline"><div class="timeline-item done"><strong>Demo booking confirmed</strong><p>Your request is saved in this browser.</p></div><div class="timeline-item"><strong>Rider assignment</strong><p>A live rider would be assigned here after launch.</p></div><div class="timeline-item"><strong>Picked up & on the way</strong><p>Live location tracking is planned for the connected service.</p></div><div class="timeline-item"><strong>A little doorstep happiness</strong><p>Your delivery is complete.</p></div></div><div class="notice">Simulation only. No live rider or GPS connection.</div><a class="textlink" href="#/help">Need a hand? Visit help ↗</a>`:`<p class="error" role="alert" style="margin-top:20px">We couldn't find this demo reference in this browser. Check your booking ID or try CM-DEMO.</p>`):'<p class="form-foot">Just exploring? Try <a href="#/track?id=CM-DEMO">CM-DEMO</a>.</p>'}</div>`}
function partners(params){let type=params.get('type')==='merchant'?'merchant':'rider';return intro('Grow with Cartman',type==='rider'?'Your drive. New possibilities.':'Your business. More doorsteps.',type==='rider'?'Explore becoming part of the Cartman rider community.':'Introduce your neighborhood favorite to a whole new neighborhood.')+`<div class="form-shell"><div class="form-content"><div class="tabs"><a class="btn ${type==='rider'?'':'outline'} full" href="#/partners?type=rider">Ride with us</a><a class="btn ${type==='merchant'?'':'outline'} full" href="#/partners?type=merchant">Business partner</a></div><h2>Let’s get acquainted.</h2><div class="notice">Prototype interest form. Details remain in your browser and are not sent to Cartman. Use sample information.</div><form id="partner-form">${field('Full name','name','text','Your name')}${field('Email address','email','email','you@example.com')}${field(type==='merchant'?'Business name':'City / municipality','location','text',type==='merchant'?'Your store name':'Where you’re based')}<label class="field">${type==='merchant'?'Business category':'Vehicle type'}<select name="category">${(type==='merchant'?['Restaurant / café','Grocery / convenience','Retail / other']:['Motorcycle','Bicycle','Other']).map(o=>`<option>${o}</option>`).join('')}</select></label><label class="check"><input type="checkbox" required><span>I understand this saves a demo application only.</span></label><button class="btn full">Save demo application ↗</button></form><div id="partner-result"></div></div><aside class="form-side"><div class="service-icon">${icon(type==='rider'?'bike':'shop')}</div><h3>Good people.<br>Going places.</h3><p>${type==='rider'?'Bring your local know-how and a people-first attitude. Learn about rider onboarding when applications open.':'Bring what makes your business special. Explore a delivery partnership built around local favorites.'}</p><p>Requirements, coverage, and commercial terms will be available before launch.</p></aside></div>`}
function account(){const u=read('cartman-session');if(!u)return auth();const bookings=read('cartman-bookings',[]);return intro('Your Cartman','Hello, '+safe(u.name)+'.','A little less to do. A little more day for you.')+`<div class="dashboard"><div class="notice">${safe(u.role[0].toUpperCase()+u.role.slice(1))} demo workspace. Information is stored locally in this browser.</div><div class="dashboard-grid"><div class="panel"><h3>${u.role==='customer'?'What’s on your list?':u.role==='rider'?'Your rider workspace':'Your merchant workspace'}</h3><p>${u.role==='customer'?'Food, groceries, parcels, or a helping hand.':u.role==='rider'?'Rider verification, availability, and job assignment will be connected before launch.':'Store verification, menu management, and live orders will be connected before launch.'}</p><a class="btn" href="#/${u.role==='customer'?'book':'partners?type='+u.role}">${u.role==='customer'?'Book a delivery':'View partner information'} ↗</a></div><div class="panel"><h3>Your profile</h3><p>${safe(u.name)}<br>${safe(u.email)}<br>${safe(u.role)} account</p><button class="btn outline" id="logout">Log out</button></div></div><div class="panel" style="margin-top:20px"><h3>Your demo deliveries</h3>${bookings.length?bookings.map(b=>`<a style="display:flex;justify-content:space-between;gap:20px;border-top:1px solid var(--line);padding:18px 0;font-size:12px" href="#/track?id=${encodeURIComponent(b.id)}"><span><strong>${safe(b.id)}</strong><br>${safe(b.pickup)} → ${safe(b.dropoff)}</span><span>₱${b.total} &nbsp; ↗</span></a>`).join(''):'<p>No deliveries yet. Your next little journey starts here.</p>'}</div></div>`}
function help(){return intro('A helping hand','How can we help?','Find a quick answer, follow a delivery, or leave a demo support request.')+`<div class="dashboard"><div class="dashboard-grid"><a class="panel" href="#/track"><h3>Where’s my delivery? ↗</h3><p>Look up a demo booking reference and see its progress.</p></a><a class="panel" href="#/account"><h3>Account & bookings ↗</h3><p>Find your profile and your saved demo deliveries.</p></a></div></div><div class="form-shell"><div class="form-content"><h2>Tell us what’s on your mind.</h2><div class="notice">Demo support form. Nothing is transmitted to a support team.</div><form id="support-form">${field('Email address','email','email','you@example.com')}<label class="field">Topic<select name="topic"><option>Delivery question</option><option>Account help</option><option>Partnership</option><option>Something else</option></select></label><label class="field">Your message<textarea name="message" required placeholder="How can we help?"></textarea></label><button class="btn full">Save demo request ↗</button></form><div id="support-result"></div></div><aside class="form-side"><h3>Here for<br>your everyday.</h3><p>Official support contact information and response hours will be added before public launch.</p></aside></div><div style="padding-bottom:60px">${faq()}</div>`}
function waitlist(){return intro('Something good is on the way','Your everyday. Coming soon.','Be ready for a simpler way to handle the little trips.')+`<div class="form-shell"><div class="form-content"><h2>Register your interest</h2><div class="notice">Preview only. This saves your preference locally; it does not subscribe you to emails.</div><form id="waitlist-form">${field('First name','name','text','Your first name')}${field('Email address','email','email','you@example.com')}${field('City','city','text','Your neighborhood')}<button class="btn full">Save launch interest ↗</button></form><div id="waitlist-result"></div></div><aside class="form-side"><h3>Your day.<br>Your way.<br>Delivered.</h3><p>Food, fresh essentials, and a little more breathing room.</p></aside></div>`}
function forgot(){return intro('Let’s get you back in','Forgot your password?','It happens. Start here to explore the recovery flow.')+`<div class="status-card"><div class="notice">Password recovery is a UI demonstration. No email will be sent.</div><form id="reset-form">${field('Email address','email','email','you@example.com')}<button class="btn full">Preview recovery request ↗</button></form><div id="reset-result"></div><p class="form-foot"><a href="#/login">← Back to login</a></p></div>`}
function legal(type){const privacy=type==='privacy';return intro('The details matter',privacy?'Your privacy matters.':'A few ground rules.','Preview notices for the Cartman PH UI MVP.')+`<article class="prose"><h2>${privacy?'About your information':'About this prototype'}</h2><p>This website is an interactive design prototype. It does not provide real deliveries, payment processing, live support, or production account access.</p><h3>${privacy?'Browser storage':'Demo use'}</h3><p>${privacy?'Demo profiles, bookings, and form entries are saved only in local storage on this device. Passwords are not retained. Use fictional details and avoid sensitive information. Clearing browser storage removes this data.':'All booking amounts, service options, timing, and tracking statuses are illustrative. Confirming a demo booking does not form a delivery contract, charge you, or dispatch a rider.'}</p><h3>Before launch</h3><p>Cartman PH must provide final service coverage, pricing, account security, customer support, and complete legal policies before accepting live customers.</p>${privacy?'<button class="btn outline" id="clear-data">Clear my demo data</button>':'<a class="btn" href="#/services">Explore services ↗</a>'}</article>`}
function slideshow(){const slides=[{src:'hero-delivery.webp',label:'More moments.<br>Fewer errands.',alt:'A Filipino courier delivers fresh groceries to a customer'},{src:'food-moment.webp',label:'Good food.<br>Better company.',alt:'Friends enjoying Filipino food together at home'},{src:'parcel-moment.webp',label:'Little packages.<br>Big possibilities.',alt:'A Filipino small business owner preparing a delivery'}];function show(n){slide=(n+slides.length)%slides.length;const s=slides[slide];$('#hero-image').src='assets/'+s.src;$('#hero-image').alt=s.alt;$('#campaign-label').innerHTML=s.label;document.querySelectorAll('[data-slide]').forEach((b,i)=>{b.classList.toggle('active',i===slide);b.setAttribute('aria-pressed',i===slide)})}document.querySelectorAll('[data-slide]').forEach(b=>b.onclick=()=>show(+b.dataset.slide));document.querySelectorAll('[data-direction]').forEach(b=>b.onclick=()=>show(slide+Number(b.dataset.direction)));let paused=matchMedia('(prefers-reduced-motion: reduce)').matches;function start(){clearInterval(slideTimer);if(!paused)slideTimer=setInterval(()=>show(slide+1),6500)}$('#pause-slide').textContent=paused?'▶':'Ⅱ';$('#pause-slide').setAttribute('aria-label',paused?'Play slideshow':'Pause slideshow');$('#pause-slide').onclick=e=>{paused=!paused;e.currentTarget.textContent=paused?'▶':'Ⅱ';e.currentTarget.setAttribute('aria-label',paused?'Play slideshow':'Pause slideshow');start()};start()}
function bind(route,params){if(route==='/')slideshow();document.querySelectorAll('[data-role]').forEach(b=>b.onclick=()=>{role=b.dataset.role;render(false)});if($('#auth-form'))$('#auth-form').onsubmit=e=>{e.preventDefault();const d=new FormData(e.target);save('cartman-session',{name:d.get('name')||String(d.get('email')).split('@')[0],email:d.get('email'),role});location.hash='/account';toast(route==='/signup'?'Your demo account is ready.':'Welcome to your demo workspace.')};if($('#booking-form')){const update=()=>$('#estimate').textContent='₱'+estimate();$('#service-select').onchange=update;$('#distance').onchange=update;if(pendingBooking){for(const [k,v]of Object.entries(pendingBooking)){const el=$('#booking-form').elements.namedItem(k);if(el)el.value=v}}update();$('#booking-form').onsubmit=e=>{e.preventDefault();pendingBooking={...Object.fromEntries(new FormData(e.target)),total:estimate()};location.hash='/review'}}if($('#confirm-booking'))$('#confirm-booking').onclick=()=>{const b={...pendingBooking,id:'CM-'+Date.now().toString(36).toUpperCase(),created:new Date().toISOString()};save('cartman-bookings',[b,...read('cartman-bookings',[])]);pendingBooking=null;location.hash='/track?id='+b.id;toast('Your demo booking is confirmed.')};if($('#track-form'))$('#track-form').onsubmit=e=>{e.preventDefault();location.hash='/track?id='+encodeURIComponent(new FormData(e.target).get('reference').trim())};if($('#logout'))$('#logout').onclick=()=>{localStorage.removeItem('cartman-session');location.hash='/login';toast('You’re logged out.')};for(const name of ['partner','support','waitlist','reset']){const form=$('#'+name+'-form');if(form)form.onsubmit=e=>{e.preventDefault();if(name!=='reset')save('cartman-'+name,Object.fromEntries(new FormData(e.target)));form.hidden=true;$('#'+name+'-result').innerHTML=`<div class="result" role="status"><h3>${name==='reset'?'Recovery flow previewed.':'All set. Saved in this browser.'}</h3><p>${name==='reset'?'In the live product, recovery instructions would be emailed if an account exists. No email has been sent.':'This is a demo confirmation. Your details have not been sent to Cartman.'}</p><a class="textlink" href="#/">Back to your day ↗</a></div>`}}if($('#clear-data'))$('#clear-data').onclick=()=>{['session','bookings','partner','support','waitlist'].forEach(k=>localStorage.removeItem('cartman-'+k));pendingBooking=null;header();toast('Your Cartman demo data has been cleared.')}}
function render(scroll=true){clearInterval(slideTimer);const raw=location.hash.slice(1)||'/';const [route,query]=raw.split('?');const params=new URLSearchParams(query);header();footer();const pages={'/':()=>home(),'/services':()=>intro('One Cartman. So many possibilities.','Whatever’s on your list.','A little help for your cravings, essentials, packages, and everyday errands.')+`<section class="section" style="padding-top:10px">${serviceCards()}</section><div class="notice">Service catalog preview. Actual coverage, partners, and rates will be confirmed at launch.</div>`,'/how-it-works':()=>intro('Simple from the start','Less to do. More you.','From your to-do list to your doorstep in three simple steps.')+`<section class="section">${steps()}</section><section class="section">${faq()}</section>`,'/login':()=>auth(),'/signup':()=>auth(true),'/forgot-password':forgot,'/book':()=>book(params),'/review':review,'/track':()=>track(params),'/partners':()=>partners(params),'/account':account,'/help':help,'/waitlist':waitlist,'/privacy':()=>legal('privacy'),'/terms':()=>legal('terms'),'/about':()=>intro('Built around your everyday','A little help goes a long way.','Cartman PH brings a simple idea to life: make everyday trips easier, and make more room for living.')+`<article class="prose"><h2>Everything. Delivered.</h2><p>From food and fresh groceries to parcels and pabili errands, this MVP imagines one familiar place for the things your day needs.</p><p>Our visual identity is inspired by the supplied Cartman PH logo: confident green, purposeful movement, and an everyday helping hand.</p><img src="assets/cartman-logo.png" alt="Original Cartman PH brand logo" style="width:100%;margin:20px 0"><a class="btn" href="#/services">Discover the possibilities ↗</a></article>`};$('#main').innerHTML=`<div class="${route==='/'?'':'wrap'}">${pages[route]?pages[route]():intro('A little detour','This page took a wrong turn.','Let’s get you back to your day.')+'<div style="text-align:center;margin:0 0 60px"><a class="btn" href="#/">Back to home ↗</a></div>'}</div>`;document.title=(route==='/'?'Your day, delivered':route.slice(1).replaceAll('-',' ').replace(/^./,c=>c.toUpperCase()))+' | Cartman PH';bind(route,params);if(scroll)window.scrollTo(0,0)}
$('.skip').onclick=e=>{e.preventDefault();$('#main').focus();$('#main').scrollIntoView()};
window.addEventListener('hashchange',()=>render());render();
